import { and, desc, eq, lte } from "drizzle-orm";

import type { ApplicationDatabaseClient } from "../database/database.server";
import {
  goalVersions,
  userPreferences,
} from "../database/schema.server";
import { localDateAt, parseIsoLocalDate } from "../food-log/date";
import type { DisplayUnits } from "../setup/validation";

export type CanonicalGoalValues = {
  calorieTargetMilliKcal: number;
  carbohydrateTargetMilligrams: number;
  fatTargetMilligrams: number;
  fiberTargetMilligrams: number;
  proteinTargetMilligrams: number;
  sodiumMaximumMilligrams: number;
  sugarMaximumMilligrams: number;
  waterTargetMicroliters: number;
};

export type GoalReplacement = CanonicalGoalValues & {
  displayUnits: DisplayUnits;
};

export class InvalidGoalVersionDateError extends Error {
  constructor() {
    super("Effective date must be today or a future local date.");
    this.name = "InvalidGoalVersionDateError";
  }
}

export class GoalVersionUnavailableError extends Error {
  constructor() {
    super("Goal Versions are unavailable for this account.");
    this.name = "GoalVersionUnavailableError";
  }
}

export class GoalVersionService {
  readonly #database: ApplicationDatabaseClient;
  readonly #now: () => Date;

  constructor(
    database: ApplicationDatabaseClient,
    now: () => Date = () => new Date(),
  ) {
    this.#database = database;
    this.#now = now;
  }

  read(userId: number, requestedDate?: string) {
    const preference = this.#database
      .select({
        displayUnits: userPreferences.displayUnits,
        timeZone: userPreferences.timeZone,
      })
      .from(userPreferences)
      .where(eq(userPreferences.userId, userId))
      .get();
    if (!preference) return undefined;

    const today = localDateAt(this.#now(), preference.timeZone);
    const selectedDate = requestedDate
      ? parseIsoLocalDate(requestedDate)
      : today;
    if (!selectedDate) throw new InvalidGoalVersionDateError();

    const goal = this.#database
      .select({
        calorieTargetMilliKcal: goalVersions.calorieTargetMilliKcal,
        carbohydrateTargetMilligrams: goalVersions.carbohydrateTargetMilligrams,
        effectiveDate: goalVersions.effectiveDate,
        fatTargetMilligrams: goalVersions.fatTargetMilligrams,
        fiberTargetMilligrams: goalVersions.fiberTargetMilligrams,
        proteinTargetMilligrams: goalVersions.proteinTargetMilligrams,
        sodiumMaximumMilligrams: goalVersions.sodiumMaximumMilligrams,
        sugarMaximumMilligrams: goalVersions.sugarMaximumMilligrams,
        waterTargetMicroliters: goalVersions.waterTargetMicroliters,
      })
      .from(goalVersions)
      .where(
        and(
          eq(goalVersions.userId, userId),
          lte(goalVersions.effectiveDate, selectedDate),
        ),
      )
      .orderBy(desc(goalVersions.effectiveDate), desc(goalVersions.id))
      .limit(1)
      .get();

    return {
      ...preference,
      displayUnits: preference.displayUnits as DisplayUnits,
      goal,
      today,
    };
  }

  replace(
    userId: number,
    effectiveDate: string,
    replacement: GoalReplacement,
  ): "created" | "replaced" {
    const now = this.#now();
    const createdAt = now.toISOString();

    return this.#database.transaction((transaction) => {
      const preference = transaction
        .select({ timeZone: userPreferences.timeZone })
        .from(userPreferences)
        .where(eq(userPreferences.userId, userId))
        .get();
      if (!preference) throw new GoalVersionUnavailableError();

      const parsedEffectiveDate = parseIsoLocalDate(effectiveDate);
      const today = localDateAt(now, preference.timeZone);
      if (!parsedEffectiveDate || parsedEffectiveDate < today) {
        throw new InvalidGoalVersionDateError();
      }

      const existing = transaction
        .select({ id: goalVersions.id })
        .from(goalVersions)
        .where(
          and(
            eq(goalVersions.userId, userId),
            eq(goalVersions.effectiveDate, parsedEffectiveDate),
          ),
        )
        .get();

      const canonicalGoalValues: CanonicalGoalValues = {
        calorieTargetMilliKcal: replacement.calorieTargetMilliKcal,
        carbohydrateTargetMilligrams:
          replacement.carbohydrateTargetMilligrams,
        fatTargetMilligrams: replacement.fatTargetMilligrams,
        fiberTargetMilligrams: replacement.fiberTargetMilligrams,
        proteinTargetMilligrams: replacement.proteinTargetMilligrams,
        sodiumMaximumMilligrams: replacement.sodiumMaximumMilligrams,
        sugarMaximumMilligrams: replacement.sugarMaximumMilligrams,
        waterTargetMicroliters: replacement.waterTargetMicroliters,
      };

      transaction
        .insert(goalVersions)
        .values({
          ...canonicalGoalValues,
          createdAt,
          effectiveDate: parsedEffectiveDate,
          userId,
        })
        .onConflictDoUpdate({
          set: {
            ...canonicalGoalValues,
            createdAt,
          },
          target: [goalVersions.userId, goalVersions.effectiveDate],
        })
        .run();

      transaction
        .update(userPreferences)
        .set({ displayUnits: replacement.displayUnits, updatedAt: createdAt })
        .where(eq(userPreferences.userId, userId))
        .run();

      return existing ? "replaced" : "created";
    });
  }
}

app/goals/validation.ts.source:
import { parseIsoLocalDate } from "../food-log/date";
import {
  validateSetupFields,
  waterTargetMicrolitersFromDisplay,
  type SetupFields,
} from "../setup/validation";
import {
  DISPLAY_UNITS,
  waterTargetThousandthsFromMicroliters,
  type DisplayUnits,
} from "./water-conversion";
import type {
  CanonicalGoalValues,
  GoalReplacement,
} from "./goal-version.server";

export type GoalVersionFields = Omit<SetupFields, "timeZone"> & {
  effectiveDate: string;
  waterSourceUnits?: string;
  waterSourceValue?: string;
};

export type GoalVersionValidationResult =
  | {
      data: GoalReplacement & { effectiveDate: string };
      success: true;
    }
  | { error: string; field: keyof GoalVersionFields; success: false };

export type CanonicalGoal = CanonicalGoalValues & {
  effectiveDate: string;
};

function formatThousandths(value: number | bigint): string {
  const fixedPoint = BigInt(value);
  const whole = fixedPoint / 1_000n;
  const fraction = String(fixedPoint % 1_000n)
    .padStart(3, "0")
    .replace(/0+$/, "");
  return fraction ? `${whole}.${fraction}` : String(whole);
}

function waterFieldFromCanonical(
  waterTargetMicroliters: number,
  displayUnits: DisplayUnits,
): string {
  const waterThousandths = waterTargetThousandthsFromMicroliters(
    waterTargetMicroliters,
    displayUnits,
  );
  return formatThousandths(waterThousandths);
}

export function convertWaterDisplay(
  value: string,
  fromUnits: DisplayUnits,
  toUnits: DisplayUnits,
): string | undefined {
  const canonical = waterTargetMicrolitersFromDisplay(value, fromUnits);
  return canonical === undefined
    ? undefined
    : waterFieldFromCanonical(canonical, toUnits);
}

export function goalFieldsFromCanonical(
  goal: CanonicalGoal,
  displayUnits: DisplayUnits,
): Omit<GoalVersionFields, "displayUnits"> {
  return {
    calories: formatThousandths(goal.calorieTargetMilliKcal),
    carbohydrate: formatThousandths(goal.carbohydrateTargetMilligrams),
    effectiveDate: goal.effectiveDate,
    fat: formatThousandths(goal.fatTargetMilligrams),
    fiber: formatThousandths(goal.fiberTargetMilligrams),
    protein: formatThousandths(goal.proteinTargetMilligrams),
    sodium: String(goal.sodiumMaximumMilligrams),
    sugar: formatThousandths(goal.sugarMaximumMilligrams),
    water: waterFieldFromCanonical(
      goal.waterTargetMicroliters,
      displayUnits,
    ),
  };
}

export function validateGoalVersionFields(
  fields: GoalVersionFields,
  timeZone: string,
  sourceGoal?: CanonicalGoal,
): GoalVersionValidationResult {
  const effectiveDate = parseIsoLocalDate(fields.effectiveDate);
  if (!effectiveDate) {
    return {
      error: "Enter a valid effective date.",
      field: "effectiveDate",
      success: false,
    };
  }

  const setup = validateSetupFields({ ...fields, timeZone });
  if (!setup.success) {
    return {
      error: setup.error,
      field: setup.field === "timeZone" ? "effectiveDate" : setup.field,
      success: false,
    };
  }

  const { timeZone: _timeZone, ...replacement } = setup.data;
  if (
    sourceGoal &&
    fields.water.trim() ===
      goalFieldsFromCanonical(sourceGoal, setup.data.displayUnits).water
  ) {
    replacement.waterTargetMicroliters = sourceGoal.waterTargetMicroliters;
  } else {
    const sourceUnits = DISPLAY_UNITS.find(
      (candidate) => candidate === fields.waterSourceUnits,
    );
    const sourceCanonical = sourceUnits
      ? waterTargetMicrolitersFromDisplay(
          fields.waterSourceValue ?? "",
          sourceUnits,
        )
      : undefined;
    if (
      sourceCanonical !== undefined &&
      fields.water.trim() ===
        waterFieldFromCanonical(sourceCanonical, setup.data.displayUnits)
    ) {
      replacement.waterTargetMicroliters = sourceCanonical;
    }
  }
  return {
    data: { ...replacement, effectiveDate },
    success: true,
  };
}

