  isRouteErrorResponse,
} from "react-router";

import stylesheet from "./styles.css?url";
import readinessStyles from "./readiness.module.css";

export const links = () => [
  { rel: "stylesheet", href: stylesheet },
  { rel: "icon", href: "/favicon.svg", type: "image/svg+xml" },
  {
    rel: "apple-touch-icon",
