export type ClientIpSources = {
  nodeEnvironment: string | undefined;
  proxyClientIp?: string;
  remoteAddress?: string;
  testClientIp?: string;
};

export function resolveClientIp({
  nodeEnvironment,
  proxyClientIp,
  remoteAddress,
  testClientIp,
}: ClientIpSources): string {
  if (nodeEnvironment === "test" && testClientIp) return testClientIp;
  return proxyClientIp ?? remoteAddress ?? "unknown";
}

server/operational-logging.js.source:
function sensitiveEnvironmentName(value) {
  return /(api.?key|authorization|cookie|credential|csrf|password|secret|session|token)/i.test(
    value,
  );
}

function configuredSensitiveValues() {
  return Object.entries(process.env)
    .filter(
      ([name, value]) =>
        sensitiveEnvironmentName(name) && value.length > 0,
    )
    .map(([, value]) => value)
    .sort((left, right) => right.length - left.length);
}

function redactText(value) {
  let redacted = value.replace(
    /((?:api.?key|authorization|cookie|credential|csrf|password|secret|session|token)=)[^&\s;]+/gi,
    "$1[REDACTED]",
  );
  for (const sensitiveValue of configuredSensitiveValues()) {
    redacted = redacted.replaceAll(sensitiveValue, "[REDACTED]");
  }
  return redacted;
}

function redact(value, key) {
  if (sensitiveEnvironmentName(key)) return "[REDACTED]";
  if (typeof value === "string") return redactText(value);
  if (Array.isArray(value)) return value.map((entry) => redact(entry));
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([entryKey, entryValue]) => [
        entryKey,
        redact(entryValue, entryKey),
      ]),
    );
  }
  return value;
}

export function operationalLog(level, event, details = {}) {
  const record = redact({
    timestamp: new Date().toISOString(),
    level,
    event,
    ...details,
  });
  const serialized = JSON.stringify(record);
  if (level === "error" || level === "warn") {
    console.error(serialized);
  } else {
    console.log(serialized);
  }
}

export function operationalError(error, includeMessage = true) {
  if (!(error instanceof Error)) {
    return includeMessage
      ? { name: "UnknownError", message: "Unknown operational failure" }
      : { name: "UnknownError" };
  }
  return includeMessage
    ? { name: error.name, message: redactText(error.message) }
    : { name: error.name };
}

server/startup-configuration.js.source:
import { isIP } from "node:net";

function privateDockerNetworkCidr(value) {
  const match = /^([^/]+)\/(\d{1,2})$/.exec(value.trim());
  if (!match || isIP(match[1]) !== 4) return false;
  const prefix = Number(match[2]);
  if (!Number.isInteger(prefix) || prefix < 16 || prefix > 32) return false;
  const octets = match[1].split(".").map(Number);
  return (
    octets[0] === 10 ||
    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) ||
    (octets[0] === 192 && octets[1] === 168)
  );
}

export function validateServerConfiguration(environment) {
  const port = Number.parseInt(environment.PORT ?? "3000", 10);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error("PORT must be an integer from 1 through 65535");
  }

  if (environment.NODE_ENV === "development") return { port };

  const applicationUrl = environment.APPLICATION_URL;
  if (!applicationUrl) {
    throw new Error("APPLICATION_URL is required outside development");
  }

  const canonicalUrl = new URL(applicationUrl);
  if (
    canonicalUrl.username ||
    canonicalUrl.password ||
    canonicalUrl.pathname !== "/" ||
    canonicalUrl.search ||
    canonicalUrl.hash
  ) {
    throw new Error(
      "APPLICATION_URL must be an origin without credentials, path, query, or hash",
    );
  }
  if (
    environment.NODE_ENV === "production" &&
    canonicalUrl.protocol !== "https:"
  ) {
    throw new Error("APPLICATION_URL must use HTTPS in production");
  }
  if (environment.NODE_ENV === "production") {
    const trustProxy = environment.TRUST_PROXY;
    if (!trustProxy || !privateDockerNetworkCidr(trustProxy)) {
      throw new Error(
        "TRUST_PROXY must be one private IPv4 Docker network CIDR with a prefix from 16 through 32",
      );
    }
  }

  return { port };
}

tests/usda-catalog-boundaries.test.ts.source:
import { afterEach, describe, expect, test, vi } from "vitest";

import {
  CatalogConfigurationError,
  CatalogCredentialsError,
  CatalogFoodNotFoundError,
  CatalogInvalidResponseError,
  CatalogRateLimitError,
  CatalogUnavailableError,
  type FoodCatalogDiagnostic,
} from "../app/catalog/food-catalog.server";
import { UsdaFoodDataCentralAdapter } from "../app/catalog/usda.server";

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    headers: { "Content-Type": "application/json" },
    status,
  });
}

function searchProvider(foods: unknown[]) {
  return new UsdaFoodDataCentralAdapter({
    apiKey: "registered-test-key",
    baseUrl: "https://example.test/fdc/v1",
    fetchImplementation: vi
      .fn<typeof fetch>()
      .mockResolvedValue(jsonResponse({ foods })),
  });
}

function foundationFood(change: Record<string, unknown> = {}) {
  return {
    dataType: "Foundation",
    description: "Boundary food",
    fdcId: 700,
    foodNutrients: [],
    ...change,
  };
}

function detailProvider(
  food: unknown,
  options: {
    onDiagnostic?: (diagnostic: FoodCatalogDiagnostic) => void;
  } = {},
) {
  return new UsdaFoodDataCentralAdapter({
    apiKey: "registered-test-key",
    baseUrl: "https://example.test/fdc/v1",
    fetchImplementation: vi.fn<typeof fetch>().mockResolvedValue(jsonResponse(food)),
    ...options,
  });
}

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllEnvs();
});

describe("USDA search boundaries", () => {
  test("normalizes Unicode text, numeric barcodes, serving aliases, and provider dates", async () => {
    const provider = searchProvider([
      {
        brandName: "  Cafe\u0301 Foods  ",
        dataType: "Branded",
        description: "  Cafe\u0301 yogurt  ",
        fdcId: 701,
        gtinUpc: " 0012345000012 ",
        householdServingFullText: "  one cup  ",
        marketCountry: " United States ",
        publicationDate: "12/3/2023",
        servingSize: 125,
        servingSizeUnit: " GRAMS ",
      },
      {
        dataType: "Foundation",
        description: "Leap-day food",
        fdcId: 702,
        publicationDate: "2024-02-29",
      },
      {
        dataType: "Foundation",
        description: "Early calendar food",
        fdcId: 703,
        publicationDate: "0100-01-02",
      },
    ]);

    await expect(provider.search("food")).resolves.toEqual([
      {
        barcode: "0012345000012",
        brand: "Café Foods",
        dataType: "Branded",
        isSelectable: true,
        measurementSummary: "one cup · 125 g",
        name: "Café yogurt",
        provider: "usda-fdc",
        providerFoodId: "701",
        providerPublishedDate: "2023-12-03",
      },
      {
        barcode: null,
        brand: null,
        dataType: "Foundation",
        isSelectable: true,
        measurementSummary: "100 g",
        name: "Leap-day food",
        provider: "usda-fdc",
        providerFoodId: "702",
        providerPublishedDate: "2024-02-29",
      },
      {
        barcode: null,
        brand: null,
        dataType: "Foundation",
        isSelectable: true,
        measurementSummary: "100 g",
        name: "Early calendar food",
        provider: "usda-fdc",
        providerFoodId: "703",
        providerPublishedDate: "0100-01-02",
      },
    ]);
  });

  test.each([
    "x2024-01-01",
    " 2024-01-01",
    "2024-01-01x",
    "2024-01-01 ",
    "2025-02-29",
    "2024-13-01",
    "2024-01-32",
    "0000-01-01",
    "x12/3/2023",
    "12/3/2023x",
    "13/3/2023",
    "12/32/2023",
    "12/3/0099",
  ])("rejects invalid provider date %s", async (publicationDate) => {
    await expect(
      searchProvider([
        {
          dataType: "Foundation",
          description: "Invalid date food",
          fdcId: 703,
          publicationDate,
        },
      ]).search("food"),
    ).rejects.toBeInstanceOf(CatalogInvalidResponseError);
  });

  test("rejects malformed barcodes without discarding otherwise valid foods", async () => {
    const foods = ["12A34", "1234 suffix", "prefix 1234"].map(
      (gtinUpc, index) => ({
        dataType: "Foundation",
        description: `Barcode ${index}`,
        fdcId: 710 + index,
        gtinUpc,
      }),
    );

    await expect(searchProvider(foods).search("food")).resolves.toMatchObject(
      foods.map((_food, index) => ({
        barcode: null,
        providerFoodId: String(710 + index),
      })),
    );
  });

  test.each([
    ["gram", "g"],
    ["grm", "g"],
    ["ml", "ml"],
    ["milliliter", "ml"],
    ["milliliters", "ml"],
    ["mlt", "ml"],
  ] as const)("normalizes serving unit %s to %s", async (servingSizeUnit, unit) => {
    await expect(
      searchProvider([
        {
          dataType: "Foundation",
          description: `${servingSizeUnit} food`,
          fdcId: 720,
          servingSize: 25,
          servingSizeUnit,
        },
      ]).search("food"),
    ).resolves.toMatchObject([{ measurementSummary: `25 ${unit}` }]);
  });

  test.each([
    { servingSize: 0, servingSizeUnit: "g" },
    { servingSize: -1, servingSizeUnit: "g" },
    { servingSize: 25, servingSizeUnit: "ounce" },
    { servingSize: null, servingSizeUnit: "g" },
    { servingSize: 25, servingSizeUnit: null },
  ])("falls back to a 100 g summary for %#", async (change) => {
    await expect(
      searchProvider([
        {
          dataType: "Foundation",
          description: "Fallback serving",
          fdcId: 721,
          ...change,
        },
      ]).search("food"),
    ).resolves.toMatchObject([{ measurementSummary: "100 g" }]);
  });

  test("deduplicates case-insensitively and retains the first equally-new revision", async () => {
    const provider = searchProvider([
      {
        brandName: "Example Brand",
        dataType: "Branded",
        description: "Case Food",
        fdcId: 730,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2025-01-01",
      },
      {
        brandName: "example brand",
        dataType: "Branded",
        description: "case food",
        fdcId: 731,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2026-01-01",
      },
      {
        brandName: "EXAMPLE BRAND",
        dataType: "Branded",
        description: "CASE FOOD",
        fdcId: 732,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2026-01-01",
      },
      {
        brandName: "Different Brand",
        dataType: "Branded",
        description: "Different barcode food",
        fdcId: 734,
        gtinUpc: "9998887776665",
        marketCountry: "United States",
        publicationDate: "2026-01-01",
      },
      {
        brandName: "Another Brand",
        dataType: "Branded",
        description: "case food",
        fdcId: 735,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2026-01-01",
      },
      {
        dataType: "Branded",
        description: "case food",
        fdcId: 736,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2026-01-01",
      },
      {
        dataType: "Branded",
        description: "CASE FOOD",
        fdcId: 737,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2027-01-01",
      },
      {
        brandName: "example brand",
        dataType: "Branded",
        description: "Different name",
        fdcId: 738,
        gtinUpc: "0001112223334",
        marketCountry: "United States",
        publicationDate: "2027-01-01",
      },
      {
        brandName: "example brand",
        dataType: "Branded",
        description: "case food",
        fdcId: 739,
        gtinUpc: "1112223334445",
        marketCountry: "United States",
        publicationDate: "2027-01-01",
      },
      {
        dataType: "Foundation",
        description: "No barcode identity",
        fdcId: 740,
      },
      {
        dataType: "Foundation",
        description: "Barcode identity",
        fdcId: 740,
        gtinUpc: "7407407407400",
      },
      {
        dataType: "Foundation",
        description: "Older provider revision",
        fdcId: 733,
        publicationDate: "2024-01-01",
      },
      {
        dataType: "Foundation",
        description: "Newer provider revision",
        fdcId: 733,
        publicationDate: "2025-01-01",
      },
    ]);

    await expect(provider.search("food")).resolves.toMatchObject([
      { providerFoodId: "731" },
      { providerFoodId: "734" },
      { providerFoodId: "735" },
      { providerFoodId: "737" },
      { providerFoodId: "738" },
      { providerFoodId: "739" },
      { name: "No barcode identity", providerFoodId: "740" },
      { name: "Barcode identity", providerFoodId: "740" },
      { name: "Newer provider revision", providerFoodId: "733" },
    ]);
  });

  test("rejects a provider description containing only whitespace", async () => {
    await expect(
      searchProvider([
        { dataType: "Foundation", description: "   ", fdcId: 735 },
      ]).search("food"),
    ).rejects.toBeInstanceOf(CatalogInvalidResponseError);
  });

  test("keeps branded and unbranded revisions distinct regardless of arrival order", async () => {
    const provider = searchProvider([
      {
        dataType: "Branded",
        description: "Shared name",
        fdcId: 741,
        gtinUpc: "7417417417410",
        marketCountry: "United States",
      },
      {
        brandName: "Later Brand",
        dataType: "Branded",
        description: "Shared name",
        fdcId: 742,
        gtinUpc: "7417417417410",
        marketCountry: "United States",
      },
    ]);

    await expect(provider.search("food")).resolves.toMatchObject([
      { brand: null, providerFoodId: "741" },
      { brand: "Later Brand", providerFoodId: "742" },
    ]);
  });

  test.each([" ", "a", "a".repeat(101)])(
    "rejects query outside the supported length: %s",
    async (query) => {
      const fetchImplementation = vi.fn<typeof fetch>();
      const provider = new UsdaFoodDataCentralAdapter({
        apiKey: "registered-test-key",
        baseUrl: "https://example.test/fdc/v1",
        fetchImplementation,
      });

      await expect(provider.search(query)).rejects.toBeInstanceOf(
        CatalogInvalidResponseError,
      );
      expect(fetchImplementation).not.toHaveBeenCalled();
    },
  );
});

describe("USDA detail normalization boundaries", () => {
  test("skips missing nutrient amounts, trims units, and diagnoses only negatives", async () => {
    const onDiagnostic = vi.fn();
    const provider = detailProvider(
      foundationFood({
        foodNutrients: [
          { amount: null, nutrient: { id: 2048, unitName: "kcal" } },
          { amount: 250, nutrient: { id: 2048, unitName: " kcal " } },
          { amount: 0, nutrient: { id: 1003, unitName: "g" } },
          { amount: -1, nutrient: { id: 1005, unitName: "g" } },
        ],
      }),
      { onDiagnostic },
    );

    await expect(provider.getFood("700")).resolves.toMatchObject({
      nutritionPerAuthoritativeBase: {
        carbohydrateMilligrams: null,
        energyMilliKcal: { amount: 250, fixedPointMultiplier: 1_000 },
        proteinMilligrams: { amount: 0, fixedPointMultiplier: 1_000 },
      },
    });
    expect(onDiagnostic).toHaveBeenCalledExactlyOnceWith({
      code: "negative_nutrient_amount",
      nutrientId: 1005,
      providerFoodId: "700",
    });
  });

  test("non-Foundation foods use label energy rather than Foundation factors", async () => {
    const provider = detailProvider({
      dataType: "Branded",
      description: "Branded energy food",
      fdcId: 700,
      foodNutrients: [
        { amount: 900, nutrient: { id: 2048, unitName: "kcal" } },
        { amount: 120, nutrient: { id: 1008, unitName: "kcal" } },
      ],
      marketCountry: "United States",
    });

    await expect(provider.getFood("700")).resolves.toMatchObject({
      nutritionPerAuthoritativeBase: {
        energyMilliKcal: { amount: 120, fixedPointMultiplier: 1_000 },
      },
    });
  });

  test("normalizes safe portions and rejects malformed or unsafe ones", async () => {
    const provider = detailProvider(
      foundationFood({
        foodPortions: [
          { amount: 0, gramWeight: 10, id: 1, portionDescription: " spoon " },
          {
            amount: -1,
            gramWeight: 20,
            id: 2,
            measureUnit: { name: "piece" },
          },
          {
            amount: 2,
            gramWeight: 30,
            id: 3,
            measureUnit: { abbreviation: "tbsp", name: "   " },
          },
          { amount: null, gramWeight: 40, id: 40, modifier: "slice" },
          { amount: 3, gramWeight: 50, id: null, modifier: "serving" },
          { amount: 1, gramWeight: 60, id: 6 },
          { amount: 1, gramWeight: 0, id: 7 },
          { amount: 1, gramWeight: -10, id: 8 },
          { amount: 1, gramWeight: Number.MAX_SAFE_INTEGER, id: 9 },
          "malformed portion",
        ],
      }),
    );

    await expect(provider.getFood("700")).resolves.toMatchObject({
      measurements: [
        { id: "portion:1", label: "1 spoon (10 g)" },
        { id: "portion:2", label: "1 piece (20 g)" },
        { id: "portion:3", label: "2 tbsp (30 g)" },
        { id: "portion:40", label: "1 slice (40 g)" },
        { id: "portion:4", label: "3 serving (50 g)" },
        { id: "portion:6", label: "1 portion (60 g)" },
        { id: "base:g:100000000", label: "100 g" },
      ],
    });
  });

  test.each([
    {
      change: { servingSize: 25, servingSizeUnit: "ml" },
      expectedUnit: "g",
    },
    {
      change: { servingSize: 0, servingSizeUnit: "g" },
      expectedUnit: "g",
    },
    {
      change: { servingSize: null, servingSizeUnit: "g" },
      expectedUnit: "g",
    },
    {
      change: { servingSize: Number.MAX_SAFE_INTEGER, servingSizeUnit: "g" },
      expectedUnit: "g",
    },
    {
      change: { servingSize: 0.000_000_1, servingSizeUnit: "g" },
      expectedUnit: "g",
    },
  ])("omits an unsafe detail serving for %#", async ({ change, expectedUnit }) => {
    const food = await detailProvider(foundationFood(change)).getFood("700");
    expect(food.authoritativeBaseUnit).toBe(expectedUnit);
    expect(food.measurements).toEqual([
      {
        baseQuantityMicrounits: 100_000_000,
        id: "base:g:100000000",
        label: "100 g",
        unit: "g",
      },
    ]);
  });

  test("a gram serving without a household label remains selectable", async () => {
    await expect(
      detailProvider(
        foundationFood({ servingSize: 25, servingSizeUnit: "g" }),
      ).getFood("700"),
    ).resolves.toMatchObject({
      measurements: [
        {
          id: "serving:g:25000000",
          label: "25 g",
          unit: "g",
        },
        { id: "base:g:100000000" },
      ],
    });
  });

  test("milliliter foods ignore gram-only provider portions", async () => {
    const provider = detailProvider({
      dataType: "Branded",
      description: "Liquid food",
      fdcId: 700,
      foodNutrients: [],
      foodPortions: [
        { amount: 1, gramWeight: 25, id: 1, modifier: "scoop" },
      ],
      marketCountry: "United States",
      servingSize: 50,
      servingSizeUnit: "ml",
    });

    const food = await provider.getFood("700");
    expect(food.authoritativeBaseUnit).toBe("ml");
    expect(food.measurements.map(({ id }) => id)).toEqual([
      "serving:ml:50000000",
      "base:ml:100000000",
    ]);
  });

  test("a branded gram serving keeps a gram authoritative base", async () => {
    const provider = detailProvider({
      dataType: "Branded",
      description: "Solid branded food",
      fdcId: 700,
      foodNutrients: [],
      marketCountry: "United States",
      servingSize: 25,
      servingSizeUnit: "g",
    });

    await expect(provider.getFood("700")).resolves.toMatchObject({
      authoritativeBaseUnit: "g",
      measurements: [
        { id: "serving:g:25000000", unit: "g" },
        { id: "base:g:100000000", unit: "g" },
      ],
    });
  });

  test("detail rejects branded foods outside the United States market", async () => {
    const provider = detailProvider({
      dataType: "Branded",
      description: "Foreign product",
      fdcId: 700,
      foodNutrients: [],
      marketCountry: "Canada",
    });

    await expect(provider.getFood("700")).rejects.toBeInstanceOf(
      CatalogInvalidResponseError,
    );
  });

  test.each(["x203", "203x"])(
    "rejects malformed abridged nutrient number %s",
    async (number) => {
      const fetchImplementation = vi
        .fn<typeof fetch>()
        .mockResolvedValueOnce(new Response(null, { status: 404 }))
        .mockResolvedValueOnce(
          jsonResponse({
            dataType: "Foundation",
            description: "Abridged boundary food",
            fdcId: 700,
            foodNutrients: [{ amount: 1, number, unitName: "G" }],
          }),
        );
      const provider = new UsdaFoodDataCentralAdapter({
        apiKey: "key",
        baseUrl: "https://example.test/fdc/v1",
        fetchImplementation,
      });

      await expect(provider.getFood("700")).rejects.toBeInstanceOf(
        CatalogInvalidResponseError,
      );
    },
  );

  test("ignores an unknown multi-decimal abridged nutrient number", async () => {
    const fetchImplementation = vi
      .fn<typeof fetch>()
      .mockResolvedValueOnce(new Response(null, { status: 404 }))
      .mockResolvedValueOnce(
        jsonResponse({
          dataType: "Foundation",
          description: "Abridged boundary food",
          fdcId: 700,
          foodNutrients: [{ amount: 1, number: "269.33", unitName: "G" }],
        }),
      );
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation,
    });

    await expect(provider.getFood("700")).resolves.toMatchObject({
      nutritionPerAuthoritativeBase: { sugarMilligrams: null },
    });
    expect(fetchImplementation.mock.calls[1]?.[1]).toMatchObject({
      method: "GET",
    });
  });
});

describe("USDA adapter request boundaries", () => {
  test("trims credentials and a trailing base slash before making a search request", async () => {
    const fetchImplementation = vi
      .fn<typeof fetch>()
      .mockResolvedValue(jsonResponse({ foods: [] }));
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "  registered-test-key  ",
      baseUrl: "https://example.test/fdc/v1/",
      fetchImplementation,
    });

    await expect(provider.search("  bread  ")).resolves.toEqual([]);

    const [url, init] = fetchImplementation.mock.calls[0];
    expect(String(url)).toBe(
      "https://example.test/fdc/v1/foods/search?api_key=registered-test-key",
    );
    expect(init).toMatchObject({
      headers: { "Content-Type": "application/json" },
      method: "POST",
    });
    expect(JSON.parse(String(init?.body))).toMatchObject({ query: "bread" });
  });

  test("rejects whitespace-only credentials", async () => {
    const fetchImplementation = vi.fn<typeof fetch>();
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "   ",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation,
    });

    await expect(provider.search("bread")).rejects.toBeInstanceOf(
      CatalogConfigurationError,
    );
    expect(fetchImplementation).not.toHaveBeenCalled();
  });

  test.each([
    "http://api.nal.usda.gov/fdc/v1",
    "https://example.test/fdc/v1",
  ])("production rejects unsafe USDA base URL %s", (baseUrl) => {
    vi.stubEnv("NODE_ENV", "production");
    expect(
      () => new UsdaFoodDataCentralAdapter({ apiKey: "key", baseUrl }),
    ).toThrow(CatalogConfigurationError);
  });

  test("production accepts the canonical USDA HTTPS endpoint", () => {
    vi.stubEnv("NODE_ENV", "production");
    expect(
      () => new UsdaFoodDataCentralAdapter({ apiKey: "key" }),
    ).not.toThrow();
  });

  test.each(["0", "01", "123suffix", "prefix123", "1.5", "-1"])(
    "rejects invalid provider food ID %s before requesting it",
    async (providerFoodId) => {
      const fetchImplementation = vi.fn<typeof fetch>();
      const provider = new UsdaFoodDataCentralAdapter({
        apiKey: "key",
        baseUrl: "https://example.test/fdc/v1",
        fetchImplementation,
      });

      await expect(provider.getFood(providerFoodId)).rejects.toBeInstanceOf(
        CatalogFoodNotFoundError,
      );
      expect(fetchImplementation).not.toHaveBeenCalled();
    },
  );

  test("rejects a detail response for a different provider ID", async () => {
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation: vi
        .fn<typeof fetch>()
        .mockResolvedValue(jsonResponse(foundationFood({ fdcId: 701 }))),
    });

    await expect(provider.getFood("700")).rejects.toBeInstanceOf(
      CatalogInvalidResponseError,
    );
  });

  test.each([
    [403, CatalogCredentialsError],
    [429, CatalogRateLimitError],
  ] as const)("detail status %s does not fall back", async (status, ErrorType) => {
    const fetchImplementation = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response(null, { status }));
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation,
    });

    await expect(provider.getFood("700")).rejects.toBeInstanceOf(ErrorType);
    expect(fetchImplementation).toHaveBeenCalledOnce();
  });

  test("an invalid JSON detail response does not fall back", async () => {
    const fetchImplementation = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response("not-json"));
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation,
    });

    await expect(provider.getFood("700")).rejects.toBeInstanceOf(
      CatalogInvalidResponseError,
    );
    expect(fetchImplementation).toHaveBeenCalledOnce();
  });

  test("successful requests clear their timeout", async () => {
    vi.useFakeTimers();
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation: vi
        .fn<typeof fetch>()
        .mockResolvedValue(jsonResponse({ foods: [] })),
      timeoutMs: 10,
    });

    await expect(provider.search("bread")).resolves.toEqual([]);
    expect(vi.getTimerCount()).toBe(0);
  });

  test("timed-out requests abort and clear their timeout", async () => {
    vi.useFakeTimers();
    const provider = new UsdaFoodDataCentralAdapter({
      apiKey: "key",
      baseUrl: "https://example.test/fdc/v1",
      fetchImplementation: vi.fn<typeof fetch>().mockImplementation(
        (_input, init) =>
          new Promise<Response>((_resolve, reject) => {
            init?.signal?.addEventListener("abort", () => {
              reject(new DOMException("provider request aborted", "AbortError"));
            });
          }),
      ),
      timeoutMs: 10,
    });

    const result = provider.search("bread");
    await Promise.all([
      expect(result).rejects.toBeInstanceOf(CatalogUnavailableError),
      vi.advanceTimersByTimeAsync(10),
    ]);
    expect(vi.getTimerCount()).toBe(0);
  });
});

tests/goal-setup.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

import { count, eq } from "drizzle-orm";
import { afterEach, expect, test } from "vitest";

import {
  openApplicationDatabase,
  type ApplicationDatabaseClient,
} from "../app/database/database.server";
import {
  goalVersions,
  userPreferences,
  users,
} from "../app/database/schema.server";
import { GoalSetupService } from "../app/setup/goal-setup.server";
import { setupClock } from "../app/setup/runtime.server";
import {
  validateSetupFields,
  type SetupSubmission,
} from "../app/setup/validation";

const temporaryDirectories: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporaryDirectories.splice(0).map((directory) =>
      rm(directory, { force: true, recursive: true }),
    ),
  );
});

async function setupDatabase() {
  const directory = await mkdtemp(path.join(tmpdir(), "calory-setup-"));
  temporaryDirectories.push(directory);
  return openApplicationDatabase({
    databasePath: path.join(directory, "application.sqlite"),
    migrationsFolder: path.resolve("drizzle"),
  });
}

function insertUser(
  client: ApplicationDatabaseClient,
  username: string,
): number {
  return client
    .insert(users)
    .values({ createdAt: "2026-01-01T00:00:00.000Z", usernameNormalized: username })
    .returning({ id: users.id })
    .get().id;
}

const canonicalSetup: SetupSubmission = {
  calorieTargetMilliKcal: 2_000_000,
  carbohydrateTargetMilligrams: 200_000,
  displayUnits: "metric",
  fatTargetMilligrams: 70_000,
  fiberTargetMilligrams: 30_000,
  proteinTargetMilligrams: 100_000,
  sodiumMaximumMilligrams: 2_000,
  sugarMaximumMilligrams: 50_000,
  timeZone: "Pacific/Honolulu",
  waterTargetMicroliters: 2_500_000,
};

test("a database failure rolls back both halves of initial setup", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const userId = insertUser(client, "atomic.user");
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T09:30:00.000Z"),
  );

  expect(() =>
    service.completeInitial(userId, {
      ...canonicalSetup,
      waterTargetMicroliters: -1,
    }),
  ).toThrow();

  expect(
    client
      .select({ value: count() })
      .from(userPreferences)
      .where(eq(userPreferences.userId, userId))
      .get()?.value,
  ).toBe(0);
  expect(
    client
      .select({ value: count() })
      .from(goalVersions)
      .where(eq(goalVersions.userId, userId))
      .get()?.value,
  ).toBe(0);
  database.close();
});

test("controlled local-date boundaries produce different initial effective dates", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const honoluluUserId = insertUser(client, "honolulu.user");
  const kiritimatiUserId = insertUser(client, "kiritimati.user");
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T09:30:00.000Z"),
  );

  expect(service.completeInitial(honoluluUserId, canonicalSetup)).toEqual({
    effectiveDate: "2025-12-31",
    ok: true,
  });
  expect(
    service.completeInitial(kiritimatiUserId, {
      ...canonicalSetup,
      timeZone: "Pacific/Kiritimati",
    }),
  ).toEqual({ effectiveDate: "2026-01-01", ok: true });
  database.close();
});

test("initial setup refuses either half of a pre-existing setup", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const preferenceUserId = insertUser(client, "preference.exists");
  const goalUserId = insertUser(client, "goal.exists");
  const createdAt = "2026-01-01T00:00:00.000Z";
  client.insert(userPreferences).values({
    createdAt,
    displayUnits: "metric",
    timeZone: "UTC",
    updatedAt: createdAt,
    userId: preferenceUserId,
  }).run();
  client.insert(goalVersions).values({
    ...canonicalSetup,
    createdAt,
    effectiveDate: "2026-01-01",
    userId: goalUserId,
  }).run();
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T12:00:00.000Z"),
  );

  expect(service.completeInitial(preferenceUserId, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
  expect(service.completeInitial(goalUserId, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
  database.close();
});

test.each([
  "SQLITE_CONSTRAINT_PRIMARYKEY",
  "SQLITE_CONSTRAINT_UNIQUE",
])("a %s race is reported as already complete", (code) => {
  const database = {
    transaction() {
      throw Object.assign(new Error("setup race"), { code });
    },
  } as unknown as ApplicationDatabaseClient;
  const service = new GoalSetupService(
    database,
    () => new Date("2026-01-01T12:00:00.000Z"),
  );

  expect(service.completeInitial(1, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
});

test.each([
  new Error("ordinary failure"),
  Object.assign(new Error("different constraint"), {
    code: "SQLITE_CONSTRAINT_CHECK",
  }),
  { code: "SQLITE_CONSTRAINT_UNIQUE" },
])("non-race setup failures are rethrown", (error) => {
  const database = {
    transaction() {
      throw error;
    },
  } as unknown as ApplicationDatabaseClient;
  const service = new GoalSetupService(database);

  expect(() => service.completeInitial(1, canonicalSetup)).toThrow(error);
});

test("validation converts display values without SQLite floating point", () => {
  expect(
    validateSetupFields({
      calories: "1800.125",
      carbohydrate: "210.125",
      displayUnits: "us",
      fat: "60.5",
      fiber: "30.75",
      protein: "90.25",
      sodium: "1900",
      sugar: "45.5",
      timeZone: "America/New_York",
      water: "80",
    }),
  ).toMatchObject({
    data: {
      calorieTargetMilliKcal: 1_800_125,
      proteinTargetMilligrams: 90_250,
      waterTargetMicroliters: 2_365_882,
    },
    success: true,
  });
});

const validSetupFields = {
  calories: "2000",
  carbohydrate: "200",
  displayUnits: "metric",
  fat: "70",
  fiber: "30",
  protein: "100",
  sodium: "2000",
  sugar: "50",
  timeZone: "America/New_York",
  water: "2500",
};

test.each([
  ["decimal prefix", { calories: "1.000junk" }, "calories"],
  ["decimal suffix", { calories: "junk1.000" }, "calories"],
  ["integer prefix", { sodium: "1junk" }, "sodium"],
  ["integer suffix", { sodium: "junk1" }, "sodium"],
  ["zero calories", { calories: "0" }, "calories"],
  ["zero water", { water: "0" }, "water"],
] as const)("validation rejects a %s", (_label, change, field) => {
  expect(validateSetupFields({ ...validSetupFields, ...change })).toMatchObject({
    field,
    success: false,
  });
});

test("validation trims numeric values and returns every canonical field", () => {
  expect(
    validateSetupFields({
      ...validSetupFields,
      calories: " 2000 ",
      sodium: " 2000 ",
      timeZone: " Pacific/Honolulu ",
    }),
  ).toEqual({
    data: {
      calorieTargetMilliKcal: 2_000_000,
      carbohydrateTargetMilligrams: 200_000,
      displayUnits: "metric",
      fatTargetMilligrams: 70_000,
      fiberTargetMilligrams: 30_000,
      proteinTargetMilligrams: 100_000,
      sodiumMaximumMilligrams: 2_000,
      sugarMaximumMilligrams: 50_000,
      timeZone: "Pacific/Honolulu",
      waterTargetMicroliters: 2_500_000,
    },
    success: true,
  });
});

test("validation enforces time-zone boundaries and exact errors", () => {
  expect(
    validateSetupFields({ ...validSetupFields, displayUnits: "imperial" }),
  ).toEqual({
    error: "Choose US or metric display units.",
    field: "displayUnits",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "" }),
  ).toMatchObject({ field: "timeZone", success: false });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "A".repeat(101) }),
  ).toEqual({
    error: "Enter a valid IANA time zone, such as America/New_York.",
    field: "timeZone",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "A".repeat(100) }),
  ).toMatchObject({ field: "timeZone", success: false });
});

test("validation exposes exact calorie, nutrient, and sodium errors", () => {
  expect(
    validateSetupFields({ ...validSetupFields, calories: "20000.001" }),
  ).toEqual({
    error: "Calories must be from 0.001 to 20,000 kcal.",
    field: "calories",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, protein: "2000.001" }),
  ).toEqual({
    error: "Protein must be from 0.001 to 2,000 g.",
    field: "protein",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, sodium: "100001" }),
  ).toEqual({
    error: "Sodium maximum must be from 1 to 100,000 mg.",
    field: "sodium",
    success: false,
  });
});

test("the setup clock only honors a valid test-only instant", () => {
  const originalNodeEnvironment = process.env.NODE_ENV;
  const originalSetupNow = process.env.SETUP_TEST_NOW;
  try {
    process.env.NODE_ENV = "test";
    process.env.SETUP_TEST_NOW = "2026-01-01T09:30:00.000Z";
    const clock = setupClock();
    expect(clock().toISOString()).toBe("2026-01-01T09:30:00.000Z");
    expect(clock()).not.toBe(clock());

    delete process.env.SETUP_TEST_NOW;
    const before = Date.now();
    expect(setupClock()().getTime()).toBeGreaterThanOrEqual(before);

    process.env.SETUP_TEST_NOW = "not-an-instant";
    expect(() => setupClock()).toThrow(
      "SETUP_TEST_NOW must be an ISO date-time",
    );

    process.env.NODE_ENV = "production";
    process.env.SETUP_TEST_NOW = "2026-01-01T09:30:00.000Z";
    expect(setupClock()().getTime()).toBeGreaterThan(
      new Date("2026-01-02T00:00:00.000Z").getTime(),
    );
  } finally {
    if (originalNodeEnvironment === undefined) delete process.env.NODE_ENV;
    else process.env.NODE_ENV = originalNodeEnvironment;
    if (originalSetupNow === undefined) delete process.env.SETUP_TEST_NOW;
    else process.env.SETUP_TEST_NOW = originalSetupNow;
  }
});

tests/authentication.security.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { createHash, createHmac } from "node:crypto";
import { tmpdir } from "node:os";
import path from "node:path";

import { eq } from "drizzle-orm";
import { afterEach, expect, test } from "vitest";

import {
  AuthenticationService,
  isUniqueConstraint,
} from "../app/auth/authentication.server";
import { hashPassword } from "../app/auth/password.server";
import { PreAuthenticationCsrfService } from "../app/auth/pre-authentication-csrf.server";
import { openApplicationDatabase } from "../app/database/database.server";
import {
  passwordCredentials,
  preAuthenticationCsrfSessions,
  rateLimitCounters,
  sessions,
} from "../app/database/schema.server";

const temporaryDirectories: string[] = [];
const password = "correct horse 🔐 battery";

afterEach(async () => {
  await Promise.all(
    temporaryDirectories.splice(0).map((directory) =>
      rm(directory, { force: true, recursive: true }),
    ),
  );
});

async function createFixture() {
  const directory = await mkdtemp(path.join(tmpdir(), "calory-auth-"));
  temporaryDirectories.push(directory);
  const applicationDatabase = openApplicationDatabase({
    databasePath: path.join(directory, "application.sqlite"),
    migrationsFolder: path.resolve("drizzle"),
  });
  let now = new Date("2026-08-29T12:00:00.000Z");
  const service = new AuthenticationService(
    applicationDatabase.getClient(),
    () => now,
  );

  return {
    applicationDatabase,
    database: applicationDatabase.getClient(),
    service,
    setNow(next: string) {
      now = new Date(next);
    },
  };
}

test("unique-constraint classification rejects lookalike and unrelated errors", () => {
  const unique = Object.assign(new Error("duplicate"), {
    code: "SQLITE_CONSTRAINT_UNIQUE",
  });
  const unrelated = Object.assign(new Error("database unavailable"), {
    code: "SQLITE_ERROR",
  });
  expect(isUniqueConstraint(unique)).toBe(true);
  expect(isUniqueConstraint(unrelated)).toBe(false);
  expect(isUniqueConstraint(new Error("missing code"))).toBe(false);
  expect(isUniqueConstraint({ code: "SQLITE_CONSTRAINT_UNIQUE" })).toBe(false);
  expect(isUniqueConstraint(null)).toBe(false);
});

test("registration distinguishes duplicates from unexpected database failures", async () => {
  const duplicateFixture = await createFixture();
  const first = await duplicateFixture.service.register(
    "duplicate.user",
    password,
    "203.0.113.90",
  );
  expect(first.ok).toBe(true);
  await expect(duplicateFixture.service.register(
    "duplicate.user",
    password,
    "203.0.113.91",
  )).resolves.toEqual({ error: "duplicate-username", ok: false });

  const brokenFixture = await createFixture();
  brokenFixture.database.$client.exec("DROP TABLE password_credentials");
  await expect(brokenFixture.service.register(
    "database.failure",
    password,
    "203.0.113.92",
  )).rejects.toThrow(/password_credentials|no such table/i);
});

test("sessions persist only a token hash and enforce idle and absolute expiry", async () => {
  const fixture = await createFixture();
  const registration = await fixture.service.register(
    "clock.user",
    password,
    "203.0.113.30",
  );
  expect(registration.ok).toBe(true);
  expect(
    fixture.database
      .select({ scope: rateLimitCounters.scope })
      .from(rateLimitCounters)
      .where(eq(rateLimitCounters.scope, "registration"))
      .get(),
  ).toEqual({ scope: "registration" });
  if (!registration.ok) throw new Error("registration failed");
  expect(Buffer.from(registration.session.token, "base64url")).toHaveLength(32);

  const storedSession = fixture.database
    .select({ tokenHash: sessions.tokenHash })
    .from(sessions)
    .get();
  expect(storedSession?.tokenHash).toMatch(/^[a-f0-9]{64}$/);
  expect(storedSession?.tokenHash).not.toContain(registration.session.token);
  const storedCredential = fixture.database
    .select({ passwordHash: passwordCredentials.passwordHash })
    .from(passwordCredentials)
    .where(
      eq(passwordCredentials.userId, registration.session.user.id),
    )
    .get();
  expect(storedCredential?.passwordHash).toMatch(/^argon2id\$v=1\$/);
  expect(storedCredential?.passwordHash).not.toContain(password);
  expect(
    (
      fixture.database.$client.pragma("table_info(sessions)") as Array<{
        name: string;
      }>
    ).map((column) => column.name),
  ).not.toContain("token");

  fixture.setNow("2026-09-03T12:00:00.000Z");
  expect(
    await fixture.service.authenticate(registration.session.token),
  ).toBeUndefined();

  fixture.setNow("2026-08-29T12:00:00.000Z");
  const activeRegistration = await fixture.service.register(
    "active.user",
    password,
    "203.0.113.31",
  );
  expect(activeRegistration.ok).toBe(true);
  if (!activeRegistration.ok) throw new Error("registration failed");

  for (let day = 4; day <= 88; day += 4) {
    fixture.setNow(
      new Date(Date.UTC(2026, 7, 29 + day, 12)).toISOString(),
    );
    expect(
      await fixture.service.authenticate(activeRegistration.session.token),
    ).toBeDefined();
  }

  fixture.setNow("2026-11-27T12:00:00.000Z");
  expect(
    await fixture.service.authenticate(activeRegistration.session.token),
  ).toBeUndefined();

  fixture.applicationDatabase.close();
});

test("successful login rehashes obsolete Argon2 parameters", async () => {
  const fixture = await createFixture();
  const registration = await fixture.service.register(
    "rehash.user",
    password,
    "203.0.113.32",
  );
  expect(registration.ok).toBe(true);

  const current = fixture.database
    .select({ passwordHash: passwordCredentials.passwordHash })
    .from(passwordCredentials)
    .get();
  if (!current) throw new Error("missing credential");
  expect(current.passwordHash).toContain("$m=64,t=1,p=1,l=32$");

  const originalNodeEnvironment = process.env.NODE_ENV;
  const originalMemory = process.env.AUTH_ARGON2_MEMORY_KIB;
  const originalPasses = process.env.AUTH_ARGON2_PASSES;
  process.env.NODE_ENV = "development";
  delete process.env.AUTH_ARGON2_MEMORY_KIB;
  delete process.env.AUTH_ARGON2_PASSES;

  try {
    const login = await fixture.service.login(
      "rehash.user",
      password,
      "203.0.113.32",
    );
    expect(login.ok).toBe(true);

    const updated = fixture.database
      .select({ passwordHash: passwordCredentials.passwordHash })
      .from(passwordCredentials)
      .get();
    expect(updated?.passwordHash).not.toBe(current.passwordHash);
    expect(updated?.passwordHash).toContain("$m=19456,t=2,p=1,l=32$");
  } finally {
    if (originalNodeEnvironment === undefined) delete process.env.NODE_ENV;
    else process.env.NODE_ENV = originalNodeEnvironment;
