  let currentSession = registration.session;
  for (let day = 4; day <= 88; day += 4) {
    fixture.setNow(
      new Date(Date.UTC(2026, 7, 29 + day, 12)).toISOString(),
    );
    const active = await fixture.service.authenticate(currentSession.token);
