    if (originalMemory === undefined) delete process.env.AUTH_ARGON2_MEMORY_KIB;
    else process.env.AUTH_ARGON2_MEMORY_KIB = originalMemory;
    if (originalPasses === undefined) delete process.env.AUTH_ARGON2_PASSES;
